.serif{font-family: "Cormorant Garamond", serif; letter-spacing: -0.055em;}
.hero{position: relative; min-height: 100svh; overflow: hidden;}
.hero video{position: absolute; inset: 0px; width: 100%; height: 100%; object-fit: cover; transform: scale(1.08); filter: saturate(1.05) contrast(1.04) brightness(0.9); will-change: transform;}
.hero::after{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle, transparent 12%, rgba(0, 0, 0, 0.18) 72%, rgba(0, 0, 0, 0.3) 100%), linear-gradient(rgba(0, 0, 0, 0.12), rgba(0, 0, 0, 0.28));}
.hero-center{position: relative; z-index: 3; min-height: 100svh; display: flex; align-items: center; justify-content: center; text-align: center; padding: 100px 24px 40px;}
.hero-inner{max-width: 1060px; padding: 0px 20px;}
.hero-title{margin-top: 26px; font-size: clamp(4.5rem, 13vw, 11rem); line-height: 0.82; letter-spacing: -0.075em; color: white; text-shadow: rgba(0, 0, 0, 0.24) 0px 18px 36px;}
.ripple{display: inline-block; animation: 8s ease-in-out 0s infinite normal none running ripple; transform-origin: center bottom;}
.hero-copy{margin: 28px auto 0px; max-width: 760px; font-size: 18px; line-height: 1.95; color: rgba(255, 255, 255, 0.88); background: rgba(255, 255, 255, 0.08); border: 1px solid rgba(255, 255, 255, 0.12); backdrop-filter: blur(30px) saturate(1.2); border-radius: 2rem; padding: 22px 26px;}
.hero-actions{display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; margin-top: 34px;}
.btn-primary{height: 58px; padding-inline: 32px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 999px; background: linear-gradient(rgba(255, 255, 255, 0.94), rgba(255, 255, 255, 0.58)); color: rgb(51, 41, 27); text-transform: uppercase; letter-spacing: 0.25em; font-size: 10px; cursor: pointer; transition: 0.45s cubic-bezier(0.16, 1, 0.3, 1); box-shadow: rgba(255, 255, 255, 0.76) 0px 1px 0px inset, rgba(0, 0, 0, 0.15) 0px 16px 42px;}
.btn-primary:hover{transform: translateY(-4px);}
.btn-secondary{height: 58px; padding-inline: 32px; border-radius: 999px; border: 1px solid rgba(255, 255, 255, 0.16); background: rgba(255, 255, 255, 0.08); color: white; text-transform: uppercase; letter-spacing: 0.25em; font-size: 10px; cursor: pointer; transition: 0.35s;}
.btn-secondary:hover{background: rgba(255, 255, 255, 0.14);}
.floating-note{position: absolute; padding: 11px 16px; border-radius: 999px; background: rgba(255, 255, 255, 0.18); color: white; border: 1px solid rgba(255, 255, 255, 0.18); backdrop-filter: blur(24px) saturate(1.2); text-transform: uppercase; letter-spacing: 0.22em; font-size: 10px; white-space: nowrap; box-shadow: rgba(0, 0, 0, 0.12) 0px 14px 32px;}
.bloom{opacity: 0; transform: translateY(26px) scale(0.98); animation-duration: 0.9s; animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1); animation-delay: 0s; animation-iteration-count: 1; animation-direction: normal; animation-fill-mode: forwards; animation-play-state: running; animation-name: bloom; animation-timeline: view(); animation-range: entry 12% cover 32%;}
